INSERT INTO reviews (parent_name, child_name, rating, text, status) VALUES
('Елена', 'сын', 5, 'Мой сын уже третий год записывается в этот лагерь. Любит его всей душой! Предлагали ему купить путёвку в большой оздоровительный лагерь в Евпаторию, согласился, только если хоть одну смену возьмём в Рыбке Долли. Мне, как родителю, тоже очень лагерь нравится. Питание отличное, досуг очень разнообразный, очень много различных мастер-классов. В общем, поругать не за что, похвалить можно много за что. Однозначно рекомендуем!', 'approved'),
('Юлия', 'дочка', 5, 'Дочка давно просилась в лагерь, но я себе даже представить не могла, что отдам её с ночёвкой в другой город! И тут мне посоветовали Рыбку Долли. В городе — для меня это приоритет! Кормят прекрасно, ребёнок счастлив, цена адекватная. Мы довольны!', 'approved'),
('Сабина', 'сын', 5, 'Закончили садик и непонятно, куда девать ребёнка на всё лето (нам нужно было на месяц). Попалось объявление про этот лагерь, решили попробовать и не прогадали. Переживали, что в лагерь ему ещё рано, только ведь после садика, но выбрали смену по возрасту — и счастью ребёнка не было предела. От Натальи Петровны он просто в восторге! Хотел ходить всё лето, еле смогли отвлечь поездкой, настолько ему было там комфортно и интересно. Особенно его восхитил их чат с вожатым и доллики, которые он заработал.', 'approved');